INSERT INTO releases (name, short_name, generation, freeze_date, key_features, description, spec_count) VALUES
('Rel-20', 'R20', '5G-Advanced', NULL, 'AI/ML-native air interface, further RedCap, ambient IoT phase 2', 'The in-progress release continuing the 5G-Advanced evolution track.', 89),
('Rel-19', 'R19', '5G-Advanced', '2025-12-19', 'Ambient IoT, AI/ML for air interface, network energy savings phase 2', 'Second full 5G-Advanced release, deepening AI/ML integration and sustainability features.', 1784),
('Rel-18', 'R18', '5G-Advanced', '2024-03-22', 'RedCap enhancements, NR-NTN, XR enhancements, AI/ML for NG-RAN', 'First 5G-Advanced release, extending 5G NR with AI/ML, non-terrestrial networks, and reduced-capability devices.', 1827),
('Rel-17', 'R17', '5G NR', '2022-03-23', 'RedCap (NR-Light), NR-NTN, multicast/broadcast, XR support', 'Extends 5G NR to new device classes and satellite access.', 1703),
('Rel-16', 'R16', '5G NR', '2020-07-03', 'NR-U unlicensed, V2X, industrial IoT, integrated access backhaul', 'Enhances 5G NR with unlicensed spectrum, vehicle-to-everything, and private network support.', 1604),
('Rel-15', 'R15', '5G NR', '2018-06-14', 'First 5G NR specifications, NSA and SA architectures', 'The foundational 5G New Radio release, defining the NR air interface and 5G core.', 1490);
INSERT INTO technologies (name, slug, full_name, description, intro_release, generation, key_specs, icon, spec_count) VALUES
('LTE', 'lte', 'Long Term Evolution', 'The foundational 4G radio access technology built around OFDMA/SC-FDMA and the flat E-UTRAN architecture.', 'Rel-8', '4G', 'TS 36.201,TS 36.300,TS 36.331,TS 36.211', '📶', 1067),
('LTE-Advanced', 'lte-advanced', 'LTE-Advanced', 'The first release to meet ITU IMT-Advanced requirements, adding carrier aggregation and higher-order MIMO.', 'Rel-10', '4G', 'TS 36.300,TS 36.101,TS 36.213', '📡', 1060),
('LTE-Advanced Pro', 'lte-advanced-pro', 'LTE-Advanced Pro', 'Extends LTE toward 5G-like capabilities with NB-IoT, LAA, and massive MIMO enhancements.', 'Rel-13', '4G', 'TS 36.300,TS 36.211,TS 36.213', '🚀', 1276),
('5G NR', '5g', '5G New Radio', 'The 5G air interface, supporting both non-standalone and standalone deployments across FR1 and FR2.', 'Rel-15', '5G', 'TS 38.201,TS 38.300,TS 38.331,TS 38.211', '🌐', 1490),
('5G-Advanced', '5g-advanced', '5G-Advanced', 'The evolution of 5G NR starting at Rel-18, adding AI/ML-native features, NTN, and RedCap enhancements.', 'Rel-18', '5G', 'TS 38.300,TS 23.501', '⚡', 1827),
('IMS', 'ims', 'IP Multimedia Subsystem', 'The access-agnostic subsystem delivering VoIP, VoLTE, VoNR, and multimedia services over IP.', 'Rel-5', '3G/4G/5G', 'TS 23.228,TS 24.229', '☎️', 220),
('EPC', 'epc', 'Evolved Packet Core', 'The all-IP core network introduced alongside LTE, comprising the MME, S-GW, and P-GW.', 'Rel-8', '4G', 'TS 23.401,TS 23.402', '🧩', 180),
('Security', 'security', '3GPP Security Architecture', 'The cross-generation set of authentication, key management, and ciphering specifications.', 'R99', 'All', 'TS 33.401,TS 33.501', '🔒', 95),
('UMTS', 'umts', 'Universal Mobile Telecommunications System', 'The original 3G system built on WCDMA radio access and an evolved GSM/GPRS core.', 'R99', '3G', 'TS 25.301,TS 23.060', '📱', 340),
('GPRS', 'gprs', 'General Packet Radio Service', 'The packet-switched overlay for GSM, providing the 3GPP packet core lineage that EPC evolved from.', 'R99', '2.5G', 'TS 23.060,TS 43.064', '📟', 130),
('5GC', '5gc', '5G Core Network', 'The service-based, cloud-native core network architecture underpinning 5G NR.', 'Rel-15', '5G', 'TS 23.501,TS 23.502,TS 29.244', '🧠', 260),
('VoLTE', 'volte', 'Voice over LTE', 'IMS-based voice service delivered natively over the LTE packet-switched network.', 'Rel-9', '4G', 'TS 23.228,TS 24.229,TS 26.114', '🎙️', 60),
('3GPP System', '3gpp-system', '3GPP System and Programme Management', 'Cross-system requirements, specification management, working methods, and programme-level documents.', 'Rel-15', 'All', 'TS 21.101,TR 21.900', NULL, 0),
('3GPP Services', '3gpp-services', '3GPP Service Requirements', 'Stage 1 service requirements and service-level capabilities spanning radio and core generations.', 'Rel-15', 'All', 'TS 22.101,TS 22.261', NULL, 0),
('Codecs & Media', 'codecs-media', '3GPP Codecs and Media', 'Speech, audio, video, and multimedia codec specifications and media handling.', 'Rel-15', 'All', 'TS 26.114,TS 26.445', NULL, 0),
('Data Services', 'data-services', '3GPP Data Services', 'Data applications, terminal data functions, and related service specifications.', 'Rel-15', 'All', NULL, NULL, 0),
('OAM & Charging', 'oam-charging', 'Operations, Administration, Maintenance and Charging', 'Network management, orchestration, charging, performance, configuration, and resource models.', 'Rel-15', 'All', 'TS 28.541,TS 32.240', NULL, 0),
('UICC & Smart Cards', 'uicc-smart-cards', 'UICC, USIM and Smart Cards', 'Subscriber identity modules, integrated circuit cards, application toolkits, and associated tests.', 'Rel-15', 'All', 'TS 31.102', NULL, 0),
('Conformance Testing', 'conformance-testing', 'UE and USIM Conformance Testing', 'Conformance and interoperability test specifications for user equipment and subscriber identity modules.', 'Rel-15', 'All', NULL, NULL, 0),
('GSM/EDGE', 'gsm-edge', 'GSM and EDGE', 'GSM-only requirements, radio, signalling, core network, and service specifications maintained in later releases.', 'Rel-15', '2G', NULL, NULL, 0),
('Multi-RAT', 'multi-rat', 'Multiple Radio Access Technologies', 'Specifications spanning multiple radio access technologies and shared-spectrum functions.', 'Rel-15', 'All', 'TS 37.213,TS 37.340', NULL, 0);
INSERT INTO glossary_terms (term, slug, full_name, definition, category, intro_release, related_specs, related_terms, evolution) VALUES
('eNodeB', 'enodeb', 'Evolved Node B', 'The LTE radio base station, combining the functions of the UMTS Node B and RNC into a single flat-architecture element that terminates the radio interface and connects directly to the EPC.', 'Radio Access Network', 'Rel-8', 'TS 36.300,TS 36.401', 'gnodeb,mme,s1ap,x2ap', 'Introduced in Rel-8 as the sole radio element of E-UTRAN, replacing the Node B/RNC split used in UMTS.'),
('gNodeB', 'gnodeb', 'Next Generation Node B', 'The 5G NR base station, capable of connecting to both 5GC (via NG) and, in non-standalone mode, acting as a secondary node alongside an eNodeB.', 'Radio Access Network', 'Rel-15', 'TS 38.300,TS 38.401', 'enodeb,amf,ngap,en-dc', 'Introduced in Rel-15; gained a disaggregated CU/DU split (F1AP) and NTN-capable variants in later releases.'),
('MME', 'mme', 'Mobility Management Entity', 'The EPC control-plane node handling NAS signaling, idle-mode UE tracking, bearer activation/deactivation, and authentication for LTE.', 'Core Network', 'Rel-8', 'TS 23.401,TS 36.413', 'enodeb,epc,s1ap,amf', 'A Rel-8 EPC function; its role is split into AMF (mobility) and SMF (session) in the 5G core.'),
('AMF', 'amf', 'Access and Mobility Management Function', 'The 5GC control-plane function handling registration, connection and mobility management, and NAS signaling termination for the UE.', 'Core Network', 'Rel-15', 'TS 23.501,TS 38.413', 'mme,smf,ngap,gnodeb', 'Introduced in Rel-15 as part of the service-based 5GC architecture, splitting MME responsibilities.'),
('SMF', 'smf', 'Session Management Function', 'The 5GC function responsible for PDU session establishment, IP address allocation, and UPF selection and control.', 'Core Network', 'Rel-15', 'TS 23.501,TS 29.244', 'amf,upf,pcf', 'Introduced in Rel-15, taking over the session-management portion of the EPC P-GW control plane.'),
('UPF', 'upf', 'User Plane Function', 'The 5GC user-plane node that performs packet routing, forwarding, QoS enforcement, and traffic reporting, with control via PFCP from the SMF.', 'Core Network', 'Rel-15', 'TS 23.501,TS 29.244', 'smf,epc,upf', 'Introduced in Rel-15 to realize control/user-plane separation (CUPS), a pattern retrofitted to EPC in parallel.'),
('PCF', 'pcf', 'Policy Control Function', 'The 5GC function that provides policy rules for QoS, charging, and traffic steering to the SMF and other network functions.', 'Core Network', 'Rel-15', 'TS 23.501,TS 23.503', 'smf,amf', 'Introduced in Rel-15 as the 5GC evolution of the EPC PCRF.'),
('UDM', 'udm', 'Unified Data Management', 'The 5GC function that stores subscriber subscription data and generates authentication credentials, exposed via the UDR.', 'Core Network', 'Rel-15', 'TS 23.501,TS 33.501', 'ausf,amf', 'Introduced in Rel-15, unifying subscriber data handling previously split across the HSS.'),
('AUSF', 'ausf', 'Authentication Server Function', 'The 5GC function that performs authentication of the UE, working with the UDM/ARPF to execute 5G-AKA or EAP-AKA procedures.', 'Security', 'Rel-15', 'TS 33.501,TS 23.501', 'udm,amf', 'Introduced in Rel-15 as a dedicated authentication function separated from the HSS role in EPC.'),
('NRF', 'nrf', 'Network Repository Function', 'The 5GC function that provides service discovery, allowing network functions to register and discover each other over the service-based interface.', 'Core Network', 'Rel-15', 'TS 23.501', 'amf,smf,pcf', 'Introduced in Rel-15 alongside the service-based architecture (SBA) that defines 5GC.'),
('NEF', 'nef', 'Network Exposure Function', 'The 5GC function that securely exposes network capabilities and events to external third-party applications.', 'Core Network', 'Rel-15', 'TS 23.501,TS 29.522', 'nrf,pcf', 'Introduced in Rel-15; expanded in later releases to expose more granular QoS and analytics events.'),
('RRC', 'rrc', 'Radio Resource Control', 'The Layer 3 protocol that manages connection establishment, mobility, and configuration of the radio interface between the UE and the network.', 'Protocol', 'R99', 'TS 38.331,TS 36.331', 'mac,pdcp,rlc', 'Present since UMTS; re-specified for E-UTRA in Rel-8 (TS 36.331) and NR in Rel-15 (TS 38.331), adding RRC_INACTIVE in NR.'),
('MAC', 'mac', 'Medium Access Control', 'The Layer 2 sublayer responsible for scheduling, HARQ, and multiplexing of logical channels onto transport channels.', 'Protocol', 'R99', 'TS 38.321,TS 36.321', 'rrc,rlc,harq', 'Re-specified for LTE (TS 36.321) and NR (TS 38.321), gaining features like multi-numerology scheduling in NR.'),
('PHY', 'phy', 'Physical Layer', 'Layer 1 of the radio protocol stack, responsible for modulation, coding, and mapping of transport channels onto physical resources.', 'Physical Layer', 'R99', 'TS 38.201,TS 36.201', 'pdsch,pusch,mcs', 'WCDMA-based in UMTS, OFDMA/SC-FDMA in LTE (Rel-8), and a flexible OFDM numerology with mmWave support in NR (Rel-15).'),
('PDCP', 'pdcp', 'Packet Data Convergence Protocol', 'The Layer 2 sublayer providing header compression, ciphering, integrity protection, and in-order delivery for user and control plane data.', 'Protocol', 'R99', 'TS 38.323,TS 36.323', 'rlc,mac,security', 'Extended in NR (Rel-15) with duplicate detection/discard to support dual connectivity and split bearers.'),
('RLC', 'rlc', 'Radio Link Control', 'The Layer 2 sublayer providing segmentation, ARQ retransmission, and in-sequence delivery between MAC and PDCP.', 'Protocol', 'R99', 'TS 38.322,TS 36.322', 'mac,pdcp', 'Simplified in NR (Rel-15) by removing concatenation, relying more on MAC-layer multiplexing.'),
('S1AP', 's1ap', 'S1 Application Protocol', 'The signaling protocol over the S1-MME interface between eNodeB and MME, carrying context setup, handover, and paging procedures.', 'Interface', 'Rel-8', 'TS 36.413', 'enodeb,mme,ngap', 'Defined in Rel-8; its 5G counterpart is NGAP over the N2 interface.'),
('X2AP', 'x2ap', 'X2 Application Protocol', 'The signaling protocol over the X2 interface between neighboring eNodeBs, used for handover preparation and interference coordination.', 'Interface', 'Rel-8', 'TS 36.423', 'enodeb,xnap', 'Defined in Rel-8; evolved into XnAP for inter-gNodeB signaling in NR (Rel-15).'),
('NGAP', 'ngap', 'NG Application Protocol', 'The signaling protocol over the N2 interface between the gNodeB and the AMF, carrying UE context and PDU session management.', 'Interface', 'Rel-15', 'TS 38.413', 'gnodeb,amf,n2', 'Introduced in Rel-15 as the NG-RAN/5GC counterpart to S1AP.'),
('XnAP', 'xnap', 'Xn Application Protocol', 'The signaling protocol over the Xn interface between NG-RAN nodes, supporting dual connectivity and mobility.', 'Interface', 'Rel-15', 'TS 38.423', 'gnodeb,x2ap', 'Introduced in Rel-15 as the 5G counterpart to X2AP.'),
('F1AP', 'f1ap', 'F1 Application Protocol', 'The signaling protocol over the F1 interface between a gNodeB-CU and gNodeB-DU in a disaggregated RAN deployment.', 'Interface', 'Rel-15', 'TS 38.473,TS 38.470', 'gnodeb,rrc', 'Introduced in Rel-15 to enable the CU/DU functional split standardized for NG-RAN.'),
('N2', 'n2', 'N2 Interface', 'The 5GC reference point between the NG-RAN and the AMF, carrying NGAP signaling.', 'Interface', 'Rel-15', 'TS 23.501,TS 38.413', 'ngap,amf,gnodeb', 'Introduced in Rel-15 as the 5G equivalent of the S1-MME interface.'),
('N3', 'n3', 'N3 Interface', 'The 5GC reference point carrying user-plane GTP-U traffic between the NG-RAN and the UPF.', 'Interface', 'Rel-15', 'TS 23.501', 'upf,gnodeb', 'Introduced in Rel-15 as the 5G equivalent of the S1-U interface.'),
('MIB', 'mib', 'Master Information Block', 'The broadcast system information carrying the minimal set of parameters a UE needs before it can read further scheduling information.', 'Physical Layer', 'Rel-8', 'TS 38.331,TS 36.331', 'sib,pbch,rrc', 'In NR (Rel-15) the MIB is carried on the PBCH within the SSB rather than on PDSCH as in LTE.'),
('SIB', 'sib', 'System Information Block', 'Broadcast messages carrying cell configuration, neighbor cell, and access-control information beyond what the MIB provides.', 'Physical Layer', 'Rel-8', 'TS 38.331,TS 36.331', 'mib,rrc', 'NR (Rel-15) introduced on-demand SIB delivery for infrequently needed system information.'),
('PRACH', 'prach', 'Physical Random Access Channel', 'The uplink physical channel used by the UE to initiate random access, enabling uplink timing synchronization and initial access.', 'Physical Layer', 'R99', 'TS 38.211,TS 36.211', 'phy,rrc', 'NR (Rel-15) introduced a 2-step RACH procedure alongside the traditional 4-step procedure, finalized in Rel-16.'),
('PDSCH', 'pdsch', 'Physical Downlink Shared Channel', 'The main downlink data-bearing physical channel, carrying user-plane and higher-layer control data scheduled via PDCCH.', 'Physical Layer', 'Rel-8', 'TS 38.211,TS 36.211', 'pdcch,mcs,tbs', 'NR (Rel-15) added flexible mapping types and mini-slot scheduling on PDSCH for low-latency use cases.'),
('PUSCH', 'pusch', 'Physical Uplink Shared Channel', 'The main uplink data-bearing physical channel, used for user-plane data and, when needed, uplink control information.', 'Physical Layer', 'Rel-8', 'TS 38.211,TS 36.211', 'pdsch,mcs', 'NR (Rel-15) introduced configured grant (grant-free) transmission on PUSCH for latency-critical traffic.'),
('PDCCH', 'pdcch', 'Physical Downlink Control Channel', 'The physical channel carrying downlink control information (DCI) that schedules PDSCH/PUSCH resources and delivers other control commands.', 'Physical Layer', 'Rel-8', 'TS 38.211,TS 36.211', 'pdsch,pusch', 'NR (Rel-15) replaced the fixed CFI-based control region with flexible CORESETs and search spaces.'),
('PUCCH', 'pucch', 'Physical Uplink Control Channel', 'The physical channel carrying uplink control information such as HARQ feedback, scheduling requests, and CSI reports.', 'Physical Layer', 'Rel-8', 'TS 38.211,TS 36.211', 'harq,csi-rs', 'NR (Rel-15) introduced multiple PUCCH formats spanning 1-14 OFDM symbols for flexible numerologies.'),
('SSB', 'ssb', 'Synchronization Signal Block', 'The NR block combining PSS, SSS, and PBCH, transmitted periodically to enable cell search, synchronization, and beam management.', 'Physical Layer', 'Rel-15', 'TS 38.211,TS 38.213', 'pbch,mib,gnodeb', 'Introduced in Rel-15 as the NR replacement for the separately-transmitted PSS/SSS/PBCH structure used in LTE.'),
('CSI-RS', 'csi-rs', 'Channel State Information Reference Signal', 'A configurable downlink reference signal used for channel quality measurement, beam management, and mobility measurements.', 'Physical Layer', 'Rel-10', 'TS 38.211,TS 36.211', 'pucch,pmi,ri,cqi', 'Introduced in LTE Rel-10 for CoMP; substantially extended in NR (Rel-15) for beam management with mmWave.'),
('DMRS', 'dmrs', 'Demodulation Reference Signal', 'UE- or beam-specific reference signal transmitted alongside data channels to enable coherent channel estimation for demodulation.', 'Physical Layer', 'Rel-8', 'TS 38.211,TS 36.211', 'pdsch,pusch', 'NR (Rel-15) added configurable DMRS density and front-loaded symbols to support low-latency demodulation.'),
('PBCH', 'pbch', 'Physical Broadcast Channel', 'The physical channel that carries the MIB, allowing a UE to acquire the minimum system information needed to access a cell.', 'Physical Layer', 'R99', 'TS 38.211,TS 36.211', 'mib,ssb', 'In NR (Rel-15), the PBCH is transmitted as part of the SSB and repeated across beams for beam sweeping.'),
('PSBCH', 'psbch', 'Physical Sidelink Broadcast Channel', 'The sidelink physical channel used to broadcast synchronization and system information directly between UEs in D2D/V2X communication.', 'Physical Layer', 'Rel-12', 'TS 36.211,TS 38.211', 'sa,phy', 'Introduced in Rel-12 for ProSe D2D; extended in Rel-14 for V2X and again in Rel-16 for NR sidelink.'),
('NR-ARFCN', 'nr-arfcn', 'NR Absolute Radio Frequency Channel Number', 'The channel numbering scheme used to identify carrier frequencies in NR across FR1 and FR2.', 'Identifier', 'Rel-15', 'TS 38.101-1,TS 38.104', 'earfcn,gnodeb', 'Introduced in Rel-15 with a wider global raster than EARFCN to accommodate FR1 and FR2 bands.'),
('EARFCN', 'earfcn', 'E-UTRA Absolute Radio Frequency Channel Number', 'The channel numbering scheme used to identify carrier frequencies for LTE bands.', 'Identifier', 'Rel-8', 'TS 36.101,TS 36.104', 'nr-arfcn,enodeb', 'Defined in Rel-8; range was extended in later releases as new LTE bands were added.'),
('RSRP', 'rsrp', 'Reference Signal Received Power', 'A UE measurement of the average power of reference signal resource elements, used for cell selection, reselection, and handover decisions.', 'Physical Layer', 'Rel-8', 'TS 36.214,TS 38.215', 'rsrq,sinr', 'Extended in NR (Rel-15) with SS-RSRP and CSI-RSRP variants measured on the SSB and CSI-RS respectively.'),
('RSRQ', 'rsrq', 'Reference Signal Received Quality', 'A UE measurement combining RSRP and received signal strength (RSSI) to indicate signal quality relative to total channel power.', 'Physical Layer', 'Rel-8', 'TS 36.214,TS 38.215', 'rsrp,sinr', 'Extended in NR (Rel-15) with SS-RSRQ and CSI-RSRQ variants.'),
('SINR', 'sinr', 'Signal-to-Interference-plus-Noise Ratio', 'A measurement expressing the ratio of desired signal power to interference and noise power, used to estimate achievable throughput.', 'Physical Layer', 'R99', 'TS 38.215,TS 36.214', 'rsrp,cqi', 'Reported as SS-SINR in NR (Rel-15) using SSB or CSI-RS resources.'),
('CQI', 'cqi', 'Channel Quality Indicator', 'UE feedback indicating the highest modulation and coding scheme the current channel conditions can support.', 'Physical Layer', 'Rel-8', 'TS 36.213,TS 38.214', 'pmi,ri,mcs', 'NR (Rel-15) added wideband and subband CQI reporting tied to configurable CSI reporting settings.'),
('PMI', 'pmi', 'Precoding Matrix Indicator', 'UE feedback recommending the precoding matrix the network should apply for closed-loop MIMO transmission.', 'Physical Layer', 'Rel-8', 'TS 36.213,TS 38.214', 'cqi,ri,csi-rs', 'NR (Rel-15) introduced Type I and Type II codebooks, with Type II giving finer-grained precoding feedback for massive MIMO.'),
('RI', 'ri', 'Rank Indicator', 'UE feedback indicating the number of spatial layers (transmission rank) that can be supported for MIMO transmission.', 'Physical Layer', 'Rel-8', 'TS 36.213,TS 38.214', 'pmi,cqi', 'NR (Rel-15) extended RI reporting to support up to 8 layers for single-user MIMO.'),
('HARQ', 'harq', 'Hybrid Automatic Repeat reQuest', 'A retransmission mechanism combining forward error correction with ARQ, using soft-combining of failed and retransmitted data.', 'Protocol', 'Rel-5', 'TS 38.321,TS 36.321', 'mac,bler', 'NR (Rel-15) reduced round-trip time versus LTE and added support for up to 16/32 HARQ processes for high-throughput scheduling.'),
('BLER', 'bler', 'Block Error Rate', 'The fraction of transport blocks received in error, used as a target metric for link adaptation and MCS selection.', 'Physical Layer', 'R99', 'TS 36.213,TS 38.214', 'harq,mcs', 'Target BLER operating points were refined in NR (Rel-15) to support ultra-reliable low-latency (URLLC) services.'),
('MCS', 'mcs', 'Modulation and Coding Scheme', 'An index mapping to a specific modulation order and code rate combination applied to a transport block.', 'Physical Layer', 'R99', 'TS 36.213,TS 38.214', 'cqi,tbs,pdsch', 'NR (Rel-15) added 256-QAM tables and, in later releases, 1024-QAM for high-SNR scenarios.'),
('TBS', 'tbs', 'Transport Block Size', 'The number of information bits contained in a transport block, derived from the MCS, allocated resource blocks, and layer count.', 'Physical Layer', 'R99', 'TS 38.214,TS 36.213', 'mcs,prb', 'NR (Rel-15) introduced a new TBS determination formula supporting a much wider range of allocation sizes than LTE.'),
('RB', 'rb', 'Radio Bearer', 'A logical connection between the UE and the network providing a defined QoS treatment for either signaling (SRB) or user data (DRB).', 'Protocol', 'R99', 'TS 38.331,TS 36.331', 'rrc,pdcp,prb', 'NR (Rel-15) retained the SRB/DRB model while adding split bearers for dual connectivity.'),
('PRB', 'prb', 'Physical Resource Block', 'The basic unit of frequency-domain resource allocation, consisting of 12 consecutive subcarriers over one slot.', 'Physical Layer', 'Rel-8', 'TS 36.211,TS 38.211', 'bwp,tbs', 'NR (Rel-15) kept the 12-subcarrier PRB definition but made its bandwidth numerology-dependent (15/30/60/120 kHz SCS).'),
('BWP', 'bwp', 'Bandwidth Part', 'A contiguous subset of the cell bandwidth that a UE is configured to operate within at a given time, enabling power-saving and mixed numerologies.', 'Physical Layer', 'Rel-15', 'TS 38.211,TS 38.213', 'prb,gnodeb', 'Introduced in Rel-15 as an NR-only concept with no direct LTE equivalent.'),
('CA', 'ca', 'Carrier Aggregation', 'The combination of multiple component carriers to increase a UE''s effective bandwidth and peak data rate.', 'Radio Access Network', 'Rel-10', 'TS 36.300,TS 38.300', 'en-dc,bwp', 'Introduced in Rel-10 as the defining LTE-Advanced feature; extended to NR intra- and inter-band CA from Rel-15 onward.'),
('EN-DC', 'en-dc', 'E-UTRA New Radio Dual Connectivity', 'A non-standalone 5G deployment option where a UE connects simultaneously to an LTE eNodeB (master) and an NR gNodeB (secondary), sharing an EPC core.', 'Radio Access Network', 'Rel-15', 'TS 37.340,TS 36.300', 'nsa,ca,gnodeb', 'Introduced in Rel-15 as the first commercially deployed 5G architecture ahead of standalone 5GC rollout.'),
('NSA', 'nsa', 'Non-Standalone', 'A 5G deployment architecture where NR radio is anchored by an existing LTE/EPC control plane, most commonly realized as EN-DC.', 'Radio Access Network', 'Rel-15', 'TS 37.340', 'en-dc,sa', 'Defined in Rel-15 as the fast-to-market 5G option, expected to be phased out as SA/5GC deployments mature.'),
('SA', 'sa', 'Standalone', 'A 5G deployment architecture where the gNodeB connects directly to the 5G core (5GC) without relying on an LTE anchor.', 'Radio Access Network', 'Rel-15', 'TS 23.501,TS 38.300', 'nsa,amf,5gc', 'Defined in Rel-15 alongside NSA; became the primary deployment target as 5GC and gNodeB maturity increased from Rel-16 onward.');
INSERT INTO specs (spec_number, spec_id, type, series, title, technology, category, network_layer, status, release, version, last_updated, ftp_url, citation_count, is_key_spec) VALUES
('TS 23.501', '23.501', 'TS', '23', '5G System Architecture', '5GC', 'Architecture', 'Core Network', 'Active', 'Rel-17', '17.9.0', '2023-06-16', 'https://www.3gpp.org/ftp/Specs/archive/23_series/23.501/', 420, 1),
('TS 23.502', '23.502', 'TS', '23', 'Procedures for the 5G System', '5GC', 'Architecture', 'Core Network', 'Active', 'Rel-17', '17.9.0', '2023-06-16', 'https://www.3gpp.org/ftp/Specs/archive/23_series/23.502/', 398, 1),
('TS 38.331', '38.331', 'TS', '38', 'NR Radio Resource Control (RRC) Protocol Specification', '5G NR', 'Protocol', 'Radio Access Network', 'Active', 'Rel-17', '17.5.0', '2023-06-23', 'https://www.3gpp.org/ftp/Specs/archive/38_series/38.331/', 385, 1),
('TS 36.331', '36.331', 'TS', '36', 'E-UTRA Radio Resource Control (RRC) Protocol Specification', 'LTE', 'Protocol', 'Radio Access Network', 'Active', 'Rel-17', '17.5.0', '2023-06-23', 'https://www.3gpp.org/ftp/Specs/archive/36_series/36.331/', 371, 1),
('TS 38.300', '38.300', 'TS', '38', 'NR and NG-RAN Overall Description', '5G NR', 'Architecture', 'Radio Access Network', 'Active', 'Rel-17', '17.4.0', '2023-04-05', 'https://www.3gpp.org/ftp/Specs/archive/38_series/38.300/', 360, 1),
('TS 36.300', '36.300', 'TS', '36', 'E-UTRA and E-UTRAN Overall Description', 'LTE', 'Architecture', 'Radio Access Network', 'Active', 'Rel-17', '17.3.0', '2023-01-11', 'https://www.3gpp.org/ftp/Specs/archive/36_series/36.300/', 349, 1),
('TS 38.213', '38.213', 'TS', '38', 'NR Physical Layer Procedures for Control', '5G NR', 'Physical Layer', 'Radio Access Network', 'Active', 'Rel-17', '17.5.0', '2023-06-23', 'https://www.3gpp.org/ftp/Specs/archive/38_series/38.213/', 338, 1),
